int main() {
    try {
        check(pb::Buffer::live_blocks() == 0);
        {
            pb::Buffer empty;
            check(empty.size() == 0);
            rejects<std::out_of_range>([&] { empty.at(0); });
            rejects<std::length_error>([] { pb::Buffer excessive(33); });
            for (std::size_t n : {std::size_t{1}, std::size_t{32}}) {
                pb::Buffer a(n);
                check(a.at(n - 1) == 0);
