        check(sizeof(seven()) == sizeof(int));
        check(calls == 0 && n == 1);
        bool left = false;
        check(!(left && ++n > 0));
        check(n == 1);
        left = true;
        check(left || ++n > 0);
        check(n == 1);
        check((0xau & 0xcu) == 8u && (0xau ^ 0xcu) == 6u);
        check(2 + 3 * 4 == 14);
        int alternate = 4;
        (left ? alternate : n) = 5; // two int lvalues preserve an assignable result
        check(alternate == 5 && n == 1);
