            }
            pb::Buffer copy(empty);
            check(copy == empty);
            check(pb::Buffer::live_blocks() == 0);
            ContainerBuffer a{{1, 2}}, b = a;
            b.values[0] = 8;
            check(a.values[0] == 1 && b.values[0] == 8);
        }
