#include <stdexcept>
#include <utility>
namespace practice {
int Buffer::blocks_ = 0;
bool Buffer::fail_next_ = false;
int* Buffer::allocate(std::size_t n) {
    if (n > 32) throw std::length_error("buffer capacity");
    if (n == 0) return nullptr;
    if (fail_next_) {
        fail_next_ = false;
        throw std::bad_alloc();
    }
    int* p = new int[n]{};
    ++blocks_;
    return p;
}
Buffer::Buffer(std::size_t n) : size_(n), data_(allocate(n)) {}
