    if (n == 0) return nullptr;
    if (fail_next_) {
        fail_next_ = false;
        throw std::bad_alloc();
    }
    int* p = new int[n]{};
    ++blocks_;
    return p;
}
Buffer::Buffer(std::size_t n) : size_(n), data_(allocate(n)) {}
