        Buffer temporary(other); // failure leaves *this unchanged
        swap(temporary);         // temporary now owns the old allocation
    }
    return *this;
}
Buffer::Buffer(Buffer&& other) noexcept { swap(other); }
Buffer& Buffer::operator=(Buffer&& other) noexcept {
    if (this != &other) {
